function openJournal(chunks) {
  let iterator;
  let iteratorAcquired = false;
  let sourceEnded = false;
  let closed = false;
  let returnPromise = null;

  let currentChunk = null;
  let chunkOffset = 0;
  let lineParts = [];
  let lineHasBytes = false;
  let lastByte = -1;
  let lineNumber = 1;

  function doneResult() {
    return { done: true, value: undefined };
  }

  function discardBufferedData() {
    currentChunk = null;
    chunkOffset = 0;
    lineParts.length = 0;
    lineHasBytes = false;
    lastByte = -1;
  }

  function acquireIterator() {
    const getIterator = chunks[Symbol.asyncIterator];

    if (typeof getIterator !== "function") {
      throw new TypeError("chunks must be an async iterable");
    }

    const source = getIterator.call(chunks);

    if (
      source === null ||
      (typeof source !== "object" && typeof source !== "function")
    ) {
      throw new TypeError("The async iterator must be an object");
    }

    iterator = source;
    iteratorAcquired = true;
  }

  function returnSource() {
    if (returnPromise !== null) {
      return returnPromise;
    }

    if (!iteratorAcquired || sourceEnded) {
      return Promise.resolve();
    }

    let resolveReturn;
    let rejectReturn;

    returnPromise = new Promise((resolve, reject) => {
      resolveReturn = resolve;
      rejectReturn = reject;
    });

    (async () => {
      try {
        const returnMethod = iterator.return;

        if (typeof returnMethod === "function") {
          await returnMethod.call(iterator);
        }

        resolveReturn();
      } catch (error) {
        rejectReturn(error);
      }
    })();

    return returnPromise;
  }

  function appendRange(bytes, start, end) {
    if (start >= end) {
      return;
    }

    lineParts.push(bytes.subarray(start, end));
    lineHasBytes = true;
    lastByte = bytes[end - 1];
  }

  function decodeCurrentLine(removeFinalCR) {
    const decoder = new TextDecoder("utf-8", { ignoreBOM: true });
    const decodedParts = [];
    const lastIndex = lineParts.length - 1;

    for (let index = 0; index < lineParts.length; index += 1) {
      let part = lineParts[index];

      if (
        removeFinalCR &&
        index === lastIndex &&
        lastByte === 0x0d
      ) {
        part = part.subarray(0, part.length - 1);
      }

      if (part.length !== 0) {
        decodedParts.push(decoder.decode(part, { stream: true }));
      }
    }

    decodedParts.push(decoder.decode());
    return decodedParts.join("");
  }

  function finishLine(removeFinalCR) {
    const line = lineNumber;
    const text = decodeCurrentLine(removeFinalCR);

    lineNumber += 1;
    lineParts.length = 0;
    lineHasBytes = false;
    lastByte = -1;

    if (text.trim().length === 0) {
      return null;
    }

    try {
      return { line, ok: true, value: JSON.parse(text) };
    } catch {
      return { line, ok: false, text };
    }
  }

  function consumeCurrentChunk() {
    if (currentChunk === null) {
      return null;
    }

    const bytes = currentChunk;
    const start = chunkOffset;
    let index = start;

    while (index < bytes.length && bytes[index] !== 0x0a) {
      index += 1;
    }

    appendRange(bytes, start, index);

    if (index === bytes.length) {
      currentChunk = null;
      chunkOffset = 0;
      return null;
    }

    chunkOffset = index + 1;

    if (chunkOffset === bytes.length) {
      currentChunk = null;
      chunkOffset = 0;
    }

    return finishLine(true);
  }

  async function next() {
    if (closed) {
      return doneResult();
    }

    try {
      for (;;) {
        if (closed) {
          return doneResult();
        }

        const event = consumeCurrentChunk();

        if (event !== null) {
          return { done: false, value: event };
        }

        if (sourceEnded) {
          if (lineHasBytes) {
            const finalEvent = finishLine(false);

            if (finalEvent !== null) {
              return { done: false, value: finalEvent };
            }

            continue;
          }

          return doneResult();
        }

        if (!iteratorAcquired) {
          acquireIterator();

          if (closed) {
            discardBufferedData();

            try {
              await returnSource();
            } catch {}

            return doneResult();
          }
        }

        const record = await iterator.next();

        if (closed) {
          discardBufferedData();
          return doneResult();
        }

        if (
          record === null ||
          (typeof record !== "object" && typeof record !== "function")
        ) {
          throw new TypeError("Iterator result must be an object");
        }

        if (record.done) {
          sourceEnded = true;
        } else {
          currentChunk = record.value;
          chunkOffset = 0;
        }
      }
    } catch (error) {
      if (closed) {
        return doneResult();
      }

      closed = true;
      discardBufferedData();

      try {
        await returnSource();
      } catch {}

      throw error;
    }
  }

  async function close() {
    if (closed) {
      if (returnPromise !== null) {
        await returnPromise;
      }
      return;
    }

    closed = true;
    discardBufferedData();

    if (iteratorAcquired && !sourceEnded) {
      await returnSource();
    }
  }

  return { next, close };
}
